export const platformScript = "// ===================== THEME =====================\nconst root = document.documentElement;\nconst themeToggle = document.getElementById('themeToggle');\nconst iconSun = document.getElementById('iconSun');\nconst iconMoon = document.getElementById('iconMoon');\nfunction setTheme(theme) {\n  root.setAttribute('data-theme', theme);\n  iconSun.style.display = theme === 'dark' ? 'block' : 'none';\n  iconMoon.style.display = theme === 'light' ? 'block' : 'none';\n  document.querySelectorAll('.appear-opt').forEach(b => b.classList.toggle('active', b.dataset.setTheme === theme));\n}\nthemeToggle.addEventListener('click', () => setTheme(root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'));\ndocument.querySelectorAll('.appear-opt').forEach(btn => btn.addEventListener('click', () => setTheme(btn.dataset.setTheme)));\n\n// ===================== DROPDOWNS =====================\nconst notifBtn = document.getElementById('notifBtn');\nconst notifDropdown = document.getElementById('notifDropdown');\nconst profileBtn = document.getElementById('profileBtn');\nconst profileDropdown = document.getElementById('profileDropdown');\nfunction closeDropdowns(except) {\n  [notifDropdown, profileDropdown].forEach(d => { if (d !== except) d.classList.remove('open'); });\n}\nnotifBtn.addEventListener('click', (e) => { e.stopPropagation(); profileDropdown.classList.remove('open'); notifDropdown.classList.toggle('open'); });\nprofileBtn.addEventListener('click', (e) => { e.stopPropagation(); notifDropdown.classList.remove('open'); profileDropdown.classList.toggle('open'); });\n\n// ===================== NOTIFICATION CENTER =====================\ndocument.querySelectorAll('.notif-tab').forEach((tab) => {\n  tab.addEventListener('click', () => {\n    document.querySelectorAll('.notif-tab').forEach((t) => t.classList.remove('active'));\n    tab.classList.add('active');\n    const cat = tab.dataset.cat;\n    document.querySelectorAll('.notif-item').forEach((item) => {\n      item.hidden = cat !== 'todas' && item.dataset.cat !== cat;\n    });\n  });\n});\ndocument.getElementById('markAllRead').addEventListener('click', () => {\n  document.querySelectorAll('.notif-item.unread').forEach((item) => item.classList.remove('unread'));\n  document.querySelector('.notif-dot').style.display = 'none';\n});\n\n// ===================== DOCUMENTOS: SEARCH + CATEGORY FILTER =====================\n(function () {\n  const docsTable = document.getElementById('docsTable');\n  if (!docsTable) return;\n  const searchInput = document.getElementById('docsSearch');\n  const catFilter = document.getElementById('docsCatFilter');\n  let activeCat = 'todos';\n\n  function applyDocsFilter() {\n    const q = (searchInput.value || '').trim().toLowerCase();\n    docsTable.querySelectorAll('tbody tr').forEach((tr) => {\n      const matchesCat = activeCat === 'todos' || tr.dataset.cat === activeCat;\n      const matchesText = !q || tr.textContent.toLowerCase().includes(q);\n      const visible = matchesCat && matchesText;\n      tr.style.display = visible ? '' : 'none';\n      if (tr.__card) tr.__card.style.display = visible ? '' : 'none';\n    });\n  }\n  searchInput.addEventListener('input', applyDocsFilter);\n  catFilter.querySelectorAll('.chip').forEach((chip) => {\n    chip.addEventListener('click', () => {\n      catFilter.querySelectorAll('.chip').forEach((c) => c.classList.remove('active'));\n      chip.classList.add('active');\n      activeCat = chip.dataset.cat;\n      applyDocsFilter();\n    });\n  });\n})();\n// ===================== DASHBOARD CUSTOMIZÁVEL =====================\n(function () {\n  const customizeBtn = document.getElementById('dashCustomizeBtn');\n  const inicioView = document.getElementById('view-inicio');\n  if (!customizeBtn || !inicioView) return;\n  const hint = document.getElementById('dashCustomizeHint');\n  const restoreTray = document.getElementById('widgetRestoreTray');\n  const kpiGrid = document.getElementById('kpiGrid');\n  const dashRowBottom = document.getElementById('dashRowBottom');\n\n  function safeStorage() {\n    try { const k = '__fortixx_test__'; localStorage.setItem(k, '1'); localStorage.removeItem(k); return localStorage; }\n    catch (e) { return null; }\n  }\n  const store = safeStorage();\n  function saveLayout() {\n    if (!store) return;\n    const order = Array.from(kpiGrid.children).concat(Array.from(dashRowBottom.children)).map((el) => el.dataset.widgetId);\n    const hidden = Array.from(inicioView.querySelectorAll('[data-widget-id].widget-hidden')).map((el) => el.dataset.widgetId);\n    try { store.setItem('fortixx_dash_layout', JSON.stringify({ order, hidden })); } catch (e) { /* ignore */ }\n  }\n  function loadLayout() {\n    if (!store) return null;\n    try { return JSON.parse(store.getItem('fortixx_dash_layout') || 'null'); } catch (e) { return null; }\n  }\n\n  function allWidgets() { return Array.from(inicioView.querySelectorAll('[data-widget-id]')); }\n\n  function refreshRestoreTray() {\n    restoreTray.innerHTML = '';\n    const hiddenWidgets = allWidgets().filter((w) => w.classList.contains('widget-hidden'));\n    restoreTray.classList.toggle('show', hiddenWidgets.length > 0 && inicioView.classList.contains('customizing'));\n    hiddenWidgets.forEach((w) => {\n      const label = w.querySelector('.kpi-label, h3')?.textContent || w.dataset.widgetId;\n      const chip = document.createElement('button');\n      chip.type = 'button';\n      chip.className = 'widget-restore-chip';\n      chip.textContent = '+ Restaurar: ' + label;\n      chip.addEventListener('click', () => { w.classList.remove('widget-hidden'); refreshRestoreTray(); saveLayout(); });\n      restoreTray.appendChild(chip);\n    });\n  }\n\n  customizeBtn.addEventListener('click', () => {\n    const active = inicioView.classList.toggle('customizing');\n    customizeBtn.classList.toggle('active', active);\n    hint.style.display = active ? 'block' : 'none';\n    allWidgets().forEach((w) => {\n      if (w.querySelector('.widget-drag-handle')) w.setAttribute('draggable', active ? 'true' : 'false');\n    });\n    refreshRestoreTray();\n  });\n\n  inicioView.querySelectorAll('.widget-hide-btn').forEach((btn) => {\n    btn.addEventListener('click', (e) => {\n      e.stopPropagation();\n      const widget = btn.closest('[data-widget-id]');\n      widget.classList.add('widget-hidden');\n      refreshRestoreTray();\n      saveLayout();\n    });\n  });\n\n  [kpiGrid, dashRowBottom].forEach((container) => {\n    let draggedEl = null;\n    container.querySelectorAll('[draggable]').forEach((item) => {\n      item.addEventListener('dragstart', () => { draggedEl = item; item.classList.add('widget-dragging'); });\n      item.addEventListener('dragend', () => {\n        item.classList.remove('widget-dragging');\n        item.classList.add('widget-snap');\n        setTimeout(() => item.classList.remove('widget-snap'), 300);\n        draggedEl = null;\n        saveLayout();\n      });\n    });\n    container.addEventListener('dragover', (e) => {\n      e.preventDefault();\n      if (!draggedEl) return;\n      const target = e.target.closest('[data-widget-id]');\n      if (!target || target === draggedEl || target.parentElement !== container) return;\n      const rect = target.getBoundingClientRect();\n      const before = e.clientX < rect.left + rect.width / 2;\n      container.insertBefore(draggedEl, before ? target : target.nextSibling);\n    });\n  });\n\n  const presets = {\n    padrao: { hidden: [] },\n    executivo: { hidden: ['panel-atividade', 'kpi-onboardings'] },\n    operacional: { hidden: ['panel-donut'] },\n    analitico: { hidden: ['panel-acoes', 'kpi-vagas'] },\n  };\n  document.getElementById('dashModeGroup').querySelectorAll('.chip').forEach((chip) => {\n    chip.addEventListener('click', () => {\n      document.querySelectorAll('#dashModeGroup .chip').forEach((c) => c.classList.remove('active'));\n      chip.classList.add('active');\n      const preset = presets[chip.dataset.mode] || presets.padrao;\n      allWidgets().forEach((w) => w.classList.toggle('widget-hidden', preset.hidden.includes(w.dataset.widgetId)));\n      refreshRestoreTray();\n      saveLayout();\n    });\n  });\n\n  document.getElementById('dashRestoreBtn').addEventListener('click', () => {\n    allWidgets().forEach((w) => w.classList.remove('widget-hidden'));\n    document.querySelectorAll('#dashModeGroup .chip').forEach((c) => c.classList.remove('active'));\n    document.querySelector('#dashModeGroup .chip[data-mode=\"padrao\"]').classList.add('active');\n    if (store) { try { store.removeItem('fortixx_dash_layout'); } catch (e) {} }\n    refreshRestoreTray();\n  });\n\n  const saved = loadLayout();\n  if (saved) {\n    if (saved.order) {\n      saved.order.forEach((id) => {\n        const el = inicioView.querySelector(`[data-widget-id=\"${id}\"]`);\n        if (el && el.parentElement === kpiGrid) kpiGrid.appendChild(el);\n        else if (el && el.parentElement === dashRowBottom) dashRowBottom.appendChild(el);\n      });\n    }\n    if (saved.hidden) saved.hidden.forEach((id) => inicioView.querySelector(`[data-widget-id=\"${id}\"]`)?.classList.add('widget-hidden'));\n  }\n})();\n\n// ===================== ANALYTICS: dept ranking animation + turnover tooltip =====================\n(function () {\n  const turnoverBars = document.querySelectorAll('#turnoverBars span');\n  const turnoverTooltip = document.getElementById('turnoverTooltip');\n  if (turnoverTooltip) {\n    turnoverBars.forEach((bar) => {\n      bar.addEventListener('mouseenter', () => {\n        turnoverTooltip.textContent = `${bar.dataset.month} — ${bar.dataset.value}`;\n        turnoverTooltip.style.left = bar.offsetLeft + bar.offsetWidth / 2 + 'px';\n        turnoverTooltip.style.top = bar.offsetTop + 'px';\n        turnoverTooltip.classList.add('show');\n      });\n      bar.addEventListener('mouseleave', () => turnoverTooltip.classList.remove('show'));\n    });\n  }\n  let deptAnimated = false;\n  function animateDeptRank() {\n    if (deptAnimated) return;\n    deptAnimated = true;\n    document.querySelectorAll('.dept-rank-bar').forEach((bar, i) => {\n      setTimeout(() => bar.classList.add('grown'), i * 90);\n    });\n  }\n\n  function formatCount(value, decimals, prefix, suffix) {\n    const fixed = value.toFixed(decimals).replace('.', ',');\n    return (prefix || '') + fixed + (suffix || '');\n  }\n  function animateKpiCounts() {\n    document.querySelectorAll('#analyticsKpiGrid [data-count-to]').forEach((el) => {\n      const target = parseFloat(el.dataset.countTo);\n      const decimals = parseInt(el.dataset.countDecimals || '0', 10);\n      const prefix = el.dataset.countPrefix || '';\n      const suffix = el.dataset.countSuffix || '';\n      const start = performance.now();\n      const duration = reduceMotion ? 50 : 1100;\n      function tick(now) {\n        const p = Math.min(1, (now - start) / duration);\n        const eased = 1 - Math.pow(1 - p, 3);\n        el.textContent = formatCount(target * eased, decimals, prefix, suffix);\n        if (p < 1) requestAnimationFrame(tick);\n      }\n      requestAnimationFrame(tick);\n    });\n  }\n  function animateSparklines() {\n    document.querySelectorAll('#analyticsKpiGrid .spark-line').forEach((line) => {\n      const len = line.getTotalLength();\n      line.style.strokeDasharray = len;\n      line.style.strokeDashoffset = reduceMotion ? 0 : len;\n      requestAnimationFrame(() => requestAnimationFrame(() => { line.style.strokeDashoffset = 0; }));\n    });\n  }\n  function animateDonuts() {\n    document.querySelectorAll('#view-analytics .donut[data-target]').forEach((donut) => {\n      const target = parseFloat(donut.dataset.target);\n      const color = donut.dataset.donutColor;\n      const label = donut.querySelector('.donut-center-label');\n      const start = performance.now();\n      const duration = reduceMotion ? 50 : 1100;\n      function tick(now) {\n        const p = Math.min(1, (now - start) / duration);\n        const eased = 1 - Math.pow(1 - p, 3);\n        const pct = (target * eased).toFixed(0);\n        donut.style.background = `conic-gradient(${color} 0% ${pct}%, var(--surface-strong) ${pct}% 100%)`;\n        if (label) label.textContent = pct + '%';\n        if (p < 1) requestAnimationFrame(tick);\n      }\n      requestAnimationFrame(tick);\n    });\n  }\n  let analyticsAnimated = false;\n  function runAnalyticsEntrance() {\n    if (analyticsAnimated) return;\n    analyticsAnimated = true;\n    animateKpiCounts();\n    animateSparklines();\n    animateDonuts();\n  }\n  document.querySelector('.dock-item[data-view=\"view-analytics\"]')?.addEventListener('click', () => {\n    setTimeout(animateDeptRank, 420);\n    setTimeout(runAnalyticsEntrance, 380);\n  });\n})();\n\n// ===================== ORGANOGRAMA: zoom, pan, search, filtro =====================\n(function () {\n  const viewport = document.getElementById('orgViewport');\n  if (!viewport) return;\n  const canvas = document.getElementById('orgCanvas');\n  let scale = 1, posX = 0, posY = 0, dragging = false, startX = 0, startY = 0;\n\n  function apply() { canvas.style.transform = `translate(-50%, 0) translate(${posX}px, ${posY}px) scale(${scale})`; }\n  function setScale(s) { scale = Math.min(1.8, Math.max(0.45, s)); apply(); }\n\n  viewport.addEventListener('mousedown', (e) => { dragging = true; viewport.classList.add('dragging'); startX = e.clientX - posX; startY = e.clientY - posY; });\n  window.addEventListener('mousemove', (e) => { if (!dragging) return; posX = e.clientX - startX; posY = e.clientY - startY; apply(); });\n  window.addEventListener('mouseup', () => { dragging = false; viewport.classList.remove('dragging'); });\n  viewport.addEventListener('touchstart', (e) => { const t = e.touches[0]; dragging = true; startX = t.clientX - posX; startY = t.clientY - posY; }, { passive: true });\n  viewport.addEventListener('touchmove', (e) => { if (!dragging) return; const t = e.touches[0]; posX = t.clientX - startX; posY = t.clientY - startY; apply(); }, { passive: true });\n  viewport.addEventListener('touchend', () => { dragging = false; });\n  viewport.addEventListener('wheel', (e) => { e.preventDefault(); setScale(scale - e.deltaY * 0.001); }, { passive: false });\n\n  document.getElementById('orgZoomIn').addEventListener('click', () => setScale(scale + 0.15));\n  document.getElementById('orgZoomOut').addEventListener('click', () => setScale(scale - 0.15));\n  document.getElementById('orgZoomReset').addEventListener('click', () => { scale = 1; posX = 0; posY = 0; apply(); });\n\n  document.getElementById('orgSearch').addEventListener('input', (e) => {\n    const q = e.target.value.trim().toLowerCase();\n    document.querySelectorAll('.org-node').forEach((n) => {\n      n.classList.toggle('highlighted', !!q && n.dataset.name.toLowerCase().includes(q));\n    });\n  });\n\n  document.getElementById('orgDeptFilter').querySelectorAll('.chip').forEach((chip) => {\n    chip.addEventListener('click', () => {\n      document.querySelectorAll('#orgDeptFilter .chip').forEach((c) => c.classList.remove('active'));\n      chip.classList.add('active');\n      const dept = chip.dataset.dept;\n      document.querySelectorAll('.org-node').forEach((n) => {\n        const match = dept === 'todos' || n.dataset.dept === dept || n.dataset.dept === 'exec';\n        n.classList.toggle('dimmed', !match);\n      });\n    });\n  });\n\n  document.querySelectorAll('.org-node[data-name]').forEach((node) => {\n    node.addEventListener('click', () => {\n      document.getElementById('drawerName').textContent = node.dataset.name;\n      document.getElementById('drawerRole').textContent = node.dataset.role;\n      document.getElementById('drawerDept').textContent = node.dataset.deptLabel;\n      document.getElementById('drawerAdmission').textContent = '—';\n      document.getElementById('drawerEmail').textContent = node.dataset.email;\n      document.getElementById('drawerPhone').textContent = node.dataset.phone;\n      document.getElementById('drawerAvatar').textContent = node.dataset.name.split(' ').map((n) => n[0]).slice(0, 2).join('');\n      drawerOverlay.classList.add('open');\n    });\n  });\n})();\n// ===================== ESCALAS: MENSAL / SEMANAL TOGGLE =====================\nconst calToggle = document.getElementById('calViewToggle');\nif (calToggle) {\n  calToggle.querySelectorAll('.chip').forEach((chip) => {\n    chip.addEventListener('click', () => {\n      calToggle.querySelectorAll('.chip').forEach((c) => c.classList.remove('active'));\n      chip.classList.add('active');\n      const isMensal = chip.dataset.calview === 'mensal';\n      document.getElementById('calMensal').style.display = isMensal ? '' : 'none';\n      document.getElementById('calSemanal').style.display = isMensal ? 'none' : 'flex';\n    });\n  });\n}\ndocument.addEventListener('click', () => closeDropdowns(null));\nnotifDropdown.addEventListener('click', (e) => e.stopPropagation());\nprofileDropdown.addEventListener('click', (e) => e.stopPropagation());\n\n// ===================== DOCK NAVIGATION =====================\nconst dock = document.getElementById('dock');\nconst dockItems = document.querySelectorAll('.dock-item');\nconst views = document.querySelectorAll('.view');\nconst pageTitle = document.getElementById('pageTitle');\nconst reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\nif (!reduceMotion) {\n  document.querySelectorAll('.kpi-card, .panel').forEach((card) => {\n    card.addEventListener('mousemove', (e) => {\n      const rect = card.getBoundingClientRect();\n      const mx = ((e.clientX - rect.left) / rect.width) * 100;\n      const my = ((e.clientY - rect.top) / rect.height) * 100;\n      card.style.setProperty('--mx', mx + '%');\n      card.style.setProperty('--my', my + '%');\n    });\n  });\n}\n\nfunction showViewSkeleton(viewEl) {\n  if (reduceMotion || !viewEl) return;\n  const overlay = document.createElement('div');\n  overlay.className = 'skeleton-overlay';\n  overlay.innerHTML = '<div class=\"sk-line\" style=\"height:30px;width:35%\"></div>' +\n    '<div style=\"display:flex;gap:16px\"><div class=\"sk-line\" style=\"height:84px;flex:1\"></div><div class=\"sk-line\" style=\"height:84px;flex:1\"></div><div class=\"sk-line\" style=\"height:84px;flex:1\"></div></div>' +\n    '<div class=\"sk-line\" style=\"height:220px;width:100%\"></div>';\n  viewEl.appendChild(overlay);\n  setTimeout(() => {\n    overlay.classList.add('fade-out');\n    setTimeout(() => overlay.remove(), 280);\n  }, 360);\n}\ndockItems.forEach(item => {\n  item.addEventListener('click', () => {\n    dockItems.forEach(d => { d.classList.remove('active'); d.removeAttribute('aria-current'); });\n    item.classList.add('active');\n    item.setAttribute('aria-current', 'page');\n    views.forEach(v => v.classList.toggle('active', v.id === item.dataset.view));\n    pageTitle.textContent = item.dataset.label;\n    window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });\n    showViewSkeleton(document.getElementById(item.dataset.view));\n  });\n});\n\nif (!reduceMotion) {\n  dock.addEventListener('mousemove', (e) => {\n    dockItems.forEach(item => {\n      const rect = item.getBoundingClientRect();\n      const center = rect.left + rect.width / 2;\n      const dist = Math.abs(e.clientX - center);\n      const maxDist = 90;\n      const scale = dist < maxDist ? 1 + (1 - dist / maxDist) * 0.32 : 1;\n      const lift = dist < maxDist ? (1 - dist / maxDist) * 10 : 0;\n      item.style.transform = `scale(${scale}) translateY(${-lift}px)`;\n    });\n  });\n  dock.addEventListener('mouseleave', () => dockItems.forEach(item => item.style.transform = ''));\n}\n\n// ===================== SUBTABS (generic) =====================\ndocument.querySelectorAll('.subtabs').forEach(group => {\n  const buttons = group.querySelectorAll('.subtab');\n  const wrapper = group.nextElementSibling;\n  buttons.forEach(btn => {\n    btn.addEventListener('click', () => {\n      buttons.forEach(b => b.classList.remove('active'));\n      btn.classList.add('active');\n      wrapper.querySelectorAll('.subview').forEach(sv => sv.classList.toggle('active', sv.id === btn.dataset.sub));\n    });\n  });\n});\n\n// ===================== CHIP GROUPS (cosmetic) =====================\ndocument.querySelectorAll('.chip-group').forEach(group => {\n  group.querySelectorAll('.chip').forEach(chip => {\n    chip.addEventListener('click', () => {\n      if (chip.textContent.trim() === '‹' || chip.textContent.trim() === '›') return;\n      group.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));\n      chip.classList.add('active');\n    });\n  });\n});\n\n// ===================== ONBOARDING EXPAND =====================\ndocument.querySelectorAll('[data-toggle-onb]').forEach(btn => {\n  btn.addEventListener('click', () => btn.closest('.onb-emp-card').classList.toggle('expanded'));\n});\n\n// ===================== ONBOARDING TASKS: marcar/desmarcar via API real =====================\nfunction updateOnbCardProgress(card) {\n  if (!card) return;\n  const tasks = card.querySelectorAll('.onb-task');\n  const doneCount = card.querySelectorAll('.onb-task.done').length;\n  const pct = tasks.length ? Math.round((doneCount / tasks.length) * 100) : 0;\n  const pctLabel = card.querySelector('.progress-row span:last-child');\n  const fill = card.querySelector('.progress-fill');\n  if (pctLabel) pctLabel.textContent = pct + '%';\n  if (fill) fill.style.width = pct + '%';\n}\nasync function toggleOnbTask(check) {\n  const taskId = check.dataset.taskId;\n  if (!taskId) return;\n  const row = check.closest('.onb-task');\n  const card = check.closest('.onb-emp-card');\n  const wasDone = row.classList.contains('done');\n  const nowDone = !wasDone;\n  row.classList.toggle('done', nowDone);\n  check.textContent = nowDone ? '✓' : '';\n  check.setAttribute('aria-checked', nowDone ? 'true' : 'false');\n  updateOnbCardProgress(card);\n  try {\n    const res = await fetch('/api/onboarding-tasks/' + taskId, {\n      method: 'PATCH',\n      credentials: 'same-origin',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ done: nowDone }),\n    });\n    if (!res.ok) {\n      const data = await res.json().catch(() => ({}));\n      throw new Error(data.error || 'Falha ao atualizar tarefa.');\n    }\n  } catch (err) {\n    row.classList.toggle('done', wasDone);\n    check.textContent = wasDone ? '✓' : '';\n    check.setAttribute('aria-checked', wasDone ? 'true' : 'false');\n    updateOnbCardProgress(card);\n    alert(err && err.message ? err.message : 'Falha ao atualizar tarefa.');\n  }\n}\ndocument.querySelectorAll('.onb-check[data-task-id]').forEach(check => {\n  check.addEventListener('click', () => toggleOnbTask(check));\n  check.addEventListener('keydown', (e) => {\n    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleOnbTask(check); }\n  });\n});\n\n// ===================== KANBAN DRAG & DROP =====================\ndocument.querySelectorAll('.kanban-card').forEach(card => {\n  card.addEventListener('dragstart', () => { card.classList.add('dragging'); window.__draggedCardId = card.id; });\n  card.addEventListener('dragend', () => card.classList.remove('dragging'));\n});\nfunction updateKanbanCounts() {\n  document.querySelectorAll('.kanban-col').forEach(col => {\n    const count = col.querySelectorAll('.kanban-card').length;\n    col.querySelector('.kanban-count').textContent = count;\n  });\n}\ndocument.querySelectorAll('.kanban-dropzone').forEach(zone => {\n  zone.addEventListener('dragover', (e) => { e.preventDefault(); zone.classList.add('drag-over'); });\n  zone.addEventListener('dragleave', () => zone.classList.remove('drag-over'));\n  zone.addEventListener('drop', (e) => {\n    e.preventDefault();\n    zone.classList.remove('drag-over');\n    const card = document.getElementById(window.__draggedCardId);\n    if (card) { zone.appendChild(card); describeKanbanCard(card); }\n    updateKanbanCounts();\n  });\n});\n\n// ===================== APPROVALS: aprovar/recusar candidato via API real =====================\nasync function handleApprovalAction(btn, action) {\n  const item = btn.closest('.approval-item');\n  const candidateId = item.dataset.candidateId;\n  const pill = item.querySelector('.status-pill');\n  const buttons = item.querySelectorAll('.approval-actions button');\n  if (!candidateId) {\n    pill.textContent = action === 'approve' ? 'Aprovado' : 'Recusado';\n    pill.className = action === 'approve' ? 'status-pill ok' : 'status-pill danger';\n    buttons.forEach(b => b.disabled = true);\n    return;\n  }\n  buttons.forEach(b => b.disabled = true);\n  const prevText = pill.textContent; const prevClass = pill.className;\n  pill.textContent = action === 'approve' ? 'Aprovando...' : 'Recusando...';\n  pill.className = 'status-pill pending';\n  try {\n    const res = await fetch('/api/recrutamento/' + candidateId + '/' + (action === 'approve' ? 'approve' : 'reject'), { method: 'POST', credentials: 'same-origin' });\n    const data = await res.json().catch(() => ({}));\n    if (!res.ok) throw new Error(data.error || 'Falha ao processar candidato.');\n    pill.textContent = action === 'approve' ? 'Aprovado' : 'Recusado';\n    pill.className = action === 'approve' ? 'status-pill ok' : 'status-pill danger';\n  } catch (err) {\n    pill.textContent = prevText; pill.className = prevClass;\n    buttons.forEach(b => b.disabled = false);\n    alert(err && err.message ? err.message : 'Falha ao processar candidato.');\n  }\n}\ndocument.querySelectorAll('.btn-approve').forEach(btn => btn.addEventListener('click', () => handleApprovalAction(btn, 'approve')));\ndocument.querySelectorAll('.btn-reject').forEach(btn => btn.addEventListener('click', () => handleApprovalAction(btn, 'reject')));\n// ===================== INVITE USER (Configurações > Usuários) =====================\n(function () {\n  const btnInvite = document.getElementById('btnInviteUser');\n  if (!btnInvite) return;\n  btnInvite.addEventListener('click', async () => {\n    const full_name = window.prompt('Nome completo do novo usuário:');\n    if (!full_name) return;\n    const email = window.prompt('E-mail do novo usuário:');\n    if (!email) return;\n    const role = window.prompt('Papel (admin, rh, gestor ou colaborador):', 'colaborador');\n    if (!role) return;\n    const password = window.prompt('Senha temporária (mínimo 8 caracteres):');\n    if (!password) return;\n    const tenantId = document.body.dataset.tenantId || null;\n    btnInvite.disabled = true;\n    try {\n      const res = await fetch('/api/onboarding', {\n        method: 'POST',\n        credentials: 'same-origin',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ full_name, email, password, role, existing_tenant_id: tenantId }),\n      });\n      const data = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error(data.error || 'Falha ao convidar usuário.');\n      alert('Usuário ' + full_name + ' criado com sucesso.');\n    } catch (err) {\n      alert(err && err.message ? err.message : 'Falha ao convidar usuário.');\n    } finally {\n      btnInvite.disabled = false;\n    }\n  });\n})();\n\n// ===================== SCHEDULE INTERVIEW (Recrutamento > Entrevistas) =====================\n(function () {\n  const btnSchedule = document.getElementById('btnScheduleInterview');\n  if (!btnSchedule) return;\n  const meta = document.getElementById('interviewSchedulerMeta');\n  let candidatesList = [];\n  let interviewersList = [];\n  try { candidatesList = JSON.parse((meta && meta.dataset.candidates) || '[]'); } catch (e) {}\n  try { interviewersList = JSON.parse((meta && meta.dataset.interviewers) || '[]'); } catch (e) {}\n  const findByName = (list, name) => {\n    const needle = name.trim().toLowerCase();\n    return list.find(item => item.full_name.trim().toLowerCase() === needle);\n  };\n  btnSchedule.addEventListener('click', async () => {\n    if (candidatesList.length === 0) { alert('Nenhum candidato cadastrado ainda.'); return; }\n    const candidateName = window.prompt('Nome do candidato:\\n' + candidatesList.map(c => '- ' + c.full_name).join('\\n'));\n    if (!candidateName) return;\n    const candidate = findByName(candidatesList, candidateName);\n    if (!candidate) { alert('Candidato não encontrado: ' + candidateName); return; }\n    const interviewerName = window.prompt('Nome do entrevistador (opcional, deixe em branco para não definir):\\n' + interviewersList.map(c => '- ' + c.full_name).join('\\n'));\n    let interviewer_id = null;\n    if (interviewerName) {\n      const interviewer = findByName(interviewersList, interviewerName);\n      if (!interviewer) { alert('Entrevistador não encontrado: ' + interviewerName); return; }\n      interviewer_id = interviewer.id;\n    }\n    const scheduledAtRaw = window.prompt('Data e hora da entrevista (AAAA-MM-DD HH:MM):');\n    if (!scheduledAtRaw) return;\n    const parsedDate = new Date(scheduledAtRaw.trim().replace(' ', 'T'));\n    if (isNaN(parsedDate.getTime())) { alert('Data/hora inválida. Use o formato AAAA-MM-DD HH:MM.'); return; }\n    btnSchedule.disabled = true;\n    try {\n      const res = await fetch('/api/interviews', {\n        method: 'POST',\n        credentials: 'same-origin',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ candidate_id: candidate.id, interviewer_id, scheduled_at: parsedDate.toISOString() }),\n      });\n      const data = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error(data.error || 'Falha ao agendar entrevista.');\n      alert('Entrevista agendada com ' + candidate.full_name + '.');\n      window.location.reload();\n    } catch (err) {\n      alert(err && err.message ? err.message : 'Falha ao agendar entrevista.');\n    } finally {\n      btnSchedule.disabled = false;\n    }\n  });\n})();\n\n// ===================== EMPLOYEE DRAWER =====================\nconst drawerOverlay = document.getElementById('drawerOverlay');\ndocument.querySelectorAll('[data-open-drawer]').forEach(btn => {\n  btn.addEventListener('click', () => {\n    document.getElementById('drawerName').textContent = btn.dataset.name;\n    document.getElementById('drawerRole').textContent = btn.dataset.role;\n    document.getElementById('drawerDept').textContent = btn.dataset.dept;\n    document.getElementById('drawerAdmission').textContent = btn.dataset.admission;\n    document.getElementById('drawerEmail').textContent = btn.dataset.email;\n    document.getElementById('drawerPhone').textContent = btn.dataset.phone;\n    document.getElementById('drawerAvatar').textContent = btn.dataset.name.split(' ').map(n => n[0]).slice(0,2).join('');\n    drawerOverlay.classList.add('open');\n  });\n});\ndocument.getElementById('drawerClose').addEventListener('click', () => drawerOverlay.classList.remove('open'));\ndrawerOverlay.addEventListener('click', (e) => { if (e.target === drawerOverlay) drawerOverlay.classList.remove('open'); });\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') { drawerOverlay.classList.remove('open'); document.getElementById('captureOverlay')?.classList.remove('open'); } });\n// ===================== SMART TABLES: refresh helper =====================\nfunction refreshTableCards(tableId) {\n  const table = document.getElementById(tableId);\n  if (!table) return;\n  const wrap = table.closest('.table-wrap');\n  const existingCards = wrap.nextElementSibling;\n  if (existingCards && existingCards.classList.contains('table-cards')) existingCards.remove();\n  delete wrap.dataset.cardsBuilt;\n  buildResponsiveTableCards();\n}\n\n  // ===================== PREMIUM CHART: draw-in + hover tooltip (reutilizável) =====================\n  function initPremiumChart(ids) {\n    const svg = document.getElementById(ids.svg);\n    if (!svg) return;\n    const path = document.getElementById(ids.crisp);\n    const glowPath = document.getElementById(ids.glow);\n    const guide = document.getElementById(ids.guide);\n    const hoverDot = document.getElementById(ids.dot);\n    const tooltip = document.getElementById(ids.tooltip);\n    const len = path.getTotalLength();\n    [path, glowPath].forEach((p) => {\n      p.style.strokeDasharray = len;\n      p.style.strokeDashoffset = reduceMotion ? 0 : len;\n      p.style.transition = 'stroke-dashoffset 1.3s cubic-bezier(.22,1,.36,1)';\n    });\n    requestAnimationFrame(() => requestAnimationFrame(() => {\n      path.style.strokeDashoffset = 0;\n      glowPath.style.strokeDashoffset = 0;\n    }));\n\n    const months = [\n      { x: 0, label: 'Jul', value: 1080 }, { x: 100, label: 'Ago', value: 1102 },\n      { x: 200, label: 'Set', value: 1118 }, { x: 300, label: 'Out', value: 1150 },\n      { x: 400, label: 'Nov', value: 1178 }, { x: 500, label: 'Dez', value: 1215 },\n      { x: 600, label: 'Jan', value: 1248 },\n    ];\n    function yAtX(targetX) {\n      let lo = 0, hi = len, best = { x: 0, y: 0 };\n      for (let i = 0; i <= 30; i++) {\n        const mid = (lo + hi) / 2;\n        const pt = path.getPointAtLength(mid);\n        best = pt;\n        if (Math.abs(pt.x - targetX) < 0.4) break;\n        if (pt.x < targetX) lo = mid; else hi = mid;\n      }\n      return best.y;\n    }\n    const markers = months.map((m) => ({ ...m, y: yAtX(m.x) }));\n    svg.addEventListener('mousemove', (e) => {\n      const rect = svg.getBoundingClientRect();\n      const mx = ((e.clientX - rect.left) / rect.width) * 600;\n      let nearest = markers[0];\n      markers.forEach((m) => { if (Math.abs(m.x - mx) < Math.abs(nearest.x - mx)) nearest = m; });\n      hoverDot.setAttribute('cx', nearest.x);\n      hoverDot.setAttribute('cy', nearest.y);\n      hoverDot.style.opacity = 1;\n      guide.setAttribute('x1', nearest.x);\n      guide.setAttribute('x2', nearest.x);\n      guide.style.opacity = 1;\n      tooltip.style.left = (nearest.x / 600 * 100) + '%';\n      tooltip.style.top = (nearest.y / 180 * 100) + '%';\n      tooltip.textContent = `${nearest.label} — ${nearest.value.toLocaleString('pt-BR')} colaboradores`;\n      tooltip.classList.add('show');\n    });\n    svg.addEventListener('mouseleave', () => {\n      hoverDot.style.opacity = 0;\n      guide.style.opacity = 0;\n      tooltip.classList.remove('show');\n    });\n  }\n\n  initPremiumChart({ svg: 'dashChartSvg', crisp: 'dashCrispLine', glow: 'dashGlowLine', guide: 'dashChartGuide', dot: 'dashHoverDot', tooltip: 'dashChartTooltip' });\n  initPremiumChart({ svg: 'analyticsChartSvg', crisp: 'analyticsCrispLine', glow: 'analyticsGlowLine', guide: 'analyticsChartGuide', dot: 'analyticsHoverDot', tooltip: 'analyticsChartTooltip' });\n\n// ===================== DOCUMENT CAPTURE (camera/gallery + OCR real via Tesseract.js) =====================\nconst captureOverlay = document.getElementById('captureOverlay');\nconst capturePreviewImg = document.getElementById('capturePreviewImg');\nconst captureFrame = document.getElementById('captureFrame');\nconst captureResult = document.getElementById('captureResult');\nconst captureSaveBtn = document.getElementById('captureSaveBtn');\nconst cameraInput = document.getElementById('cameraInput');\nconst galleryInput = document.getElementById('galleryInput');\nconst btnOpenCamera = document.getElementById('btnOpenCamera');\nconst btnOpenGallery = document.getElementById('btnOpenGallery');\n\nif (btnOpenCamera && btnOpenGallery) {\n  btnOpenCamera.addEventListener('click', () => cameraInput.click());\n  btnOpenGallery.addEventListener('click', () => galleryInput.click());\n\n  const CAT_LABEL = { identidade: 'Identidade (RG / CPF)', comprovante: 'Comprovante de residência', contrato: 'Contrato', curriculo: 'Currículo', outro: 'Documento' };\n  let ocrWorker = null;\n  let pendingFile = null;\n\n  function stepState(name, state) {\n    const el = document.querySelector('#captureSteps .capture-step[data-step=\"' + name + '\"]');\n    if (!el) return;\n    el.classList.remove('active', 'done');\n    if (state) el.classList.add(state);\n  }\n  function resetCaptureModal() {\n    capturePreviewImg.style.display = 'none';\n    captureFrame.classList.remove('show');\n    document.querySelectorAll('#captureSteps .capture-step').forEach(s => s.classList.remove('active', 'done'));\n    captureResult.classList.remove('show');\n    captureSaveBtn.style.display = 'none';\n    captureSaveBtn.disabled = false;\n  }\n\n  function normalize(s) { return (s || '').normalize('NFD').replace(/[\\u0300-\\u036f]/g, ''); }\n  function classify(txt) {\n    const u = normalize(txt).toUpperCase();\n    if (/IDENTIDADE|REPUBLICA FEDERATIVA|REGISTRO GERAL|SECRETARIA DE SEGURANCA|CARTEIRA DE IDENT/.test(u)) return 'identidade';\n    if (/COMPROVANTE|CONTA DE (LUZ|ENERGIA|AGUA)|FATURA|CEMIG|ENEL|COPEL|SABESP|LIGHT|EQUATORIAL/.test(u)) return 'comprovante';\n    if (/CONTRATO|CLAUSULA|CONTRATANTE|CONTRATAD[OA]|RESCIS/.test(u)) return 'contrato';\n    if (/CURRIC|CURRICULO|EXPERIENCIA PROFISSIONAL|FORMACAO ACADEMICA|OBJETIVO PROFISSIONAL/.test(u)) return 'curriculo';\n    return 'outro';\n  }\n  function parseDoc(txt) {\n    const clean = txt.replace(/[ \\t]+/g, ' ');\n    const cpf = (clean.match(/\\b\\d{3}\\.?\\s?\\d{3}\\.?\\s?\\d{3}\\s?[-.]?\\s?\\d{2}\\b/) || [null])[0];\n    const rg = (clean.match(/\\b\\d{1,2}\\.?\\d{3}\\.?\\d{3}\\s?-?\\s?[\\dxX]\\b/) || [null])[0];\n    const data = (clean.match(/\\b\\d{2}\\/\\d{2}\\/\\d{4}\\b/) || [null])[0];\n    let nome = null;\n    const lines = txt.split(/\\r?\\n/).map(l => l.trim()).filter(Boolean);\n    const LABEL = /^(CONTRATAD[OA]|NOME|CLIENTE|TITULAR|BENEFICIARIO|BENEFICIÁRIO)\\b\\s*[:.\\-]?\\s*(.*)$/i;\n    for (let i = 0; i < lines.length; i++) {\n      const m = lines[i].match(LABEL);\n      if (!m) continue;\n      const inline = (m[2] || '').trim();\n      nome = inline.length > 3 ? inline : (lines[i + 1] || null);\n      if (nome) break;\n    }\n    if (!nome) {\n      const cand = lines.find(l => /^[A-ZÀ-Ú][A-ZÀ-Ú '.]{6,}$/.test(l) && l.split(' ').length >= 2 && !/REPUBLICA|IDENTIDADE|SECRETARIA|GERAL|FEDERATIVA|CONTRATO|CARTEIRA|FATURA|ENERGIA/.test(normalize(l).toUpperCase()));\n      if (cand) nome = cand.replace(/\\s{2,}/g, ' ');\n    }\n    return { cpf, rg, data, nome, doc: cpf || rg || null };\n  }\n\n  async function runOcr(file) {\n    stepState('crop', 'done'); stepState('enhance', 'done'); stepState('ocr', 'active');\n    if (typeof Tesseract === 'undefined') {\n      document.getElementById('captureDocType').textContent = 'OCR indisponível — recarregue a página';\n      captureResult.classList.add('show');\n      return;\n    }\n    if (!ocrWorker) {\n      ocrWorker = await Tesseract.createWorker('por', 1, {\n        workerPath: '/tesseract/worker.min.js',\n        corePath: '/tesseract/',\n        langPath: '/tesseract/',\n        logger: m => {\n          if (m.status === 'recognizing text') {\n            const el = document.querySelector('#captureSteps .capture-step[data-step=\"ocr\"]');\n            if (el) el.textContent = 'Lendo o documento (OCR) — ' + Math.round(m.progress * 100) + '%';\n          }\n        },\n      });\n    }\n    const { data } = await ocrWorker.recognize(file);\n    stepState('ocr', 'done'); stepState('classify', 'active');\n    const text = data.text || '';\n    const conf = Math.round((data.confidence || 0) * 10) / 10;\n    const cat = classify(text);\n    const parsed = parseDoc(text);\n    stepState('classify', 'done');\n    captureFrame.classList.remove('show');\n\n    const badge = captureResult.querySelector('.badge-illustrative');\n    if (badge) { badge.textContent = 'Leitura automática (OCR no navegador)'; }\n    document.getElementById('captureDocType').textContent = 'Documento identificado: ' + CAT_LABEL[cat];\n    document.getElementById('captureFieldName').textContent = parsed.nome || '—';\n    document.getElementById('captureFieldDoc').textContent = parsed.doc || parsed.data || '—';\n    const rows = captureResult.querySelectorAll('.drawer-row span:last-child');\n    if (rows[2]) rows[2].textContent = conf + '%';\n    captureResult.classList.add('show');\n    captureSaveBtn.style.display = 'block';\n    captureSaveBtn.dataset.payload = JSON.stringify({ category: cat, confidence: conf, extracted: { tipo: cat, nome: parsed.nome, cpf: parsed.cpf, rg: parsed.rg, data: parsed.data, texto: text.slice(0, 4000) } });\n  }\n\n  function handleCaptureFile(file) {\n    if (!file) return;\n    pendingFile = file;\n    resetCaptureModal();\n    captureOverlay.classList.add('open');\n    if (file.type && file.type.startsWith('image/')) {\n      const reader = new FileReader();\n      reader.onload = (e) => {\n        capturePreviewImg.src = e.target.result;\n        capturePreviewImg.style.display = 'block';\n        captureFrame.classList.add('show');\n        runOcr(file).catch(err => {\n          document.getElementById('captureDocType').textContent = 'Falha ao ler: ' + (err && err.message ? err.message : 'erro no OCR');\n          captureResult.classList.add('show');\n        });\n      };\n      reader.readAsDataURL(file);\n    } else {\n      // PDF: sem preview de imagem; ainda dá pra salvar (sem OCR client-side)\n      document.getElementById('captureDocType').textContent = 'PDF — será salvo sem leitura automática';\n      document.getElementById('captureFieldName').textContent = '—';\n      document.getElementById('captureFieldDoc').textContent = file.name;\n      captureResult.classList.add('show');\n      captureSaveBtn.style.display = 'block';\n      captureSaveBtn.dataset.payload = JSON.stringify({ category: '', confidence: 0, extracted: null });\n    }\n  }\n  cameraInput.addEventListener('change', (e) => handleCaptureFile(e.target.files[0]));\n  galleryInput.addEventListener('change', (e) => handleCaptureFile(e.target.files[0]));\n\n  captureSaveBtn.addEventListener('click', async () => {\n    if (!pendingFile) return;\n    stepState('save', 'active');\n    captureSaveBtn.disabled = true;\n    const payload = JSON.parse(captureSaveBtn.dataset.payload || '{}');\n    const fd = new FormData();\n    fd.append('file', pendingFile);\n    fd.append('category', payload.category || '');\n    fd.append('confidence', String(payload.confidence || 0));\n    if (payload.extracted) fd.append('extracted', JSON.stringify(payload.extracted));\n    try {\n      const res = await fetch('/api/documents/upload', { method: 'POST', credentials: 'same-origin', body: fd });\n      const data = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error(data.error || 'Falha ao salvar.');\n      stepState('save', 'done');\n      const d = data.document || {};\n      const catLabel = CAT_LABEL[d.category] || 'Documento';\n      const pill = d.ocr_status === 'baixa_confianca' ? '<span class=\\\"status-pill pending\\\">Baixa confiança</span>' : '<span class=\\\"status-pill pending\\\">Em análise</span>';\n      const tbody = document.querySelector('#docsTable tbody');\n      if (tbody) {\n        const tr = document.createElement('tr');\n        tr.setAttribute('data-cat', d.category || 'outro');\n        tr.innerHTML = '<td>' + (d.file_name || 'documento') + '</td><td><span class=\\\"tag\\\">' + catLabel + '</span></td><td>Você</td><td>agora</td><td>' + pill + '</td>';\n        tbody.insertBefore(tr, tbody.firstChild);\n        if (typeof refreshTableCards === 'function') refreshTableCards('docsTable');\n      }\n      captureOverlay.classList.remove('open');\n      cameraInput.value = ''; galleryInput.value = ''; pendingFile = null;\n    } catch (err) {\n      captureSaveBtn.disabled = false;\n      stepState('save', null);\n      alert(err && err.message ? err.message : 'Falha ao salvar o documento.');\n    }\n  });\n\n  document.getElementById('captureClose').addEventListener('click', () => captureOverlay.classList.remove('open'));\n  captureOverlay.addEventListener('click', (e) => { if (e.target === captureOverlay) captureOverlay.classList.remove('open'); });\n}\n\n// ===================== ASSISTENTE RH: Atendimento (chat real) + Escalonamento =====================\n(function () {\n  const log = document.getElementById('chatLog');\n  const input = document.getElementById('chatInput');\n  const send = document.getElementById('chatSend');\n  if (log && input && send) {\n    const layout = document.querySelector('.chat-layout[data-assistant-enabled]');\n    const enabled = !layout || layout.dataset.assistantEnabled === '1';\n    let conversationId = null;\n    const first = document.querySelector('.chat-list-item[data-conversation-id]');\n    if (first) conversationId = first.dataset.conversationId;\n    const bubble = (role, text) => {\n      const el = document.createElement('div');\n      el.className = 'chat-bubble ' + (role === 'user' ? 'user' : 'bot');\n      el.textContent = text;\n      log.appendChild(el);\n      log.scrollTop = log.scrollHeight;\n      return el;\n    };\n    document.querySelectorAll('.chat-list-item[data-conversation-id]').forEach(item => {\n      item.addEventListener('click', () => {\n        document.querySelectorAll('.chat-list-item').forEach(i => i.classList.remove('active'));\n        item.classList.add('active');\n        conversationId = item.dataset.conversationId;\n        log.innerHTML = '';\n        bubble('bot', 'Escreva abaixo para continuar este atendimento.');\n      });\n    });\n    const submit = async () => {\n      const message = input.value.trim();\n      if (!message) return;\n      if (!enabled) { bubble('bot', 'Assistente desligado: falta ANTHROPIC_API_KEY no ambiente.'); return; }\n      input.value = '';\n      input.disabled = true; send.disabled = true;\n      bubble('user', message);\n      const pending = bubble('bot', 'Digitando...');\n      try {\n        const res = await fetch('/api/hr-assistant', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ conversation_id: conversationId, message }) });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok) throw new Error(data.error || 'Falha ao falar com o assistente.');\n        conversationId = data.conversation_id || conversationId;\n        pending.textContent = data.answer || 'Encaminhei para o RH.';\n        if (data.escalated) bubble('bot', 'Este atendimento foi encaminhado para uma pessoa do RH.');\n      } catch (err) {\n        pending.textContent = (err && err.message) ? err.message : 'Erro ao consultar o assistente.';\n      } finally {\n        input.disabled = false; send.disabled = false; input.focus();\n      }\n    };\n    send.addEventListener('click', submit);\n    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); submit(); } });\n  }\n  document.querySelectorAll('.btn-hr-resolve').forEach(btn => {\n    btn.addEventListener('click', async () => {\n      const card = btn.closest('[data-conversation-id]');\n      if (!card) return;\n      btn.disabled = true;\n      try {\n        const res = await fetch('/api/hr-assistant/' + card.dataset.conversationId, { method: 'PATCH', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'resolved' }) });\n        if (!res.ok) { const d = await res.json().catch(() => ({})); throw new Error(d.error || 'Falha ao resolver.'); }\n        card.remove();\n      } catch (err) { btn.disabled = false; alert((err && err.message) ? err.message : 'Falha ao resolver.'); }\n    });\n  });\n})();\n\n// ===================== MEU PERFIL =====================\nconst goToProfileLink = document.getElementById('goToProfile');\nconst backFromProfile = document.getElementById('backFromProfile');\nconst saveProfileBtn = document.getElementById('saveProfileBtn');\n\ngoToProfileLink.addEventListener('click', () => {\n  views.forEach(v => v.classList.toggle('active', v.id === 'view-perfil'));\n  dockItems.forEach(d => { d.classList.remove('active'); d.removeAttribute('aria-current'); });\n  pageTitle.textContent = 'Meu perfil';\n  closeDropdowns(null);\n  window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });\n});\n\nbackFromProfile.addEventListener('click', () => {\n  document.querySelector('.dock-item[data-view=\"view-inicio\"]').click();\n});\n\nif (saveProfileBtn) {\n  saveProfileBtn.addEventListener('click', () => {\n    saveProfileBtn.textContent = 'Salvo ✓';\n    setTimeout(() => { saveProfileBtn.textContent = 'Salvar alterações'; }, 1800);\n  });\n}\n\n// ===================== SMART TABLES (mobile cards) =====================\nfunction buildResponsiveTableCards() {\n  document.querySelectorAll('.table-wrap').forEach(wrap => {\n    const table = wrap.querySelector('.data-table');\n    if (!table || wrap.dataset.cardsBuilt) return;\n    wrap.dataset.cardsBuilt = '1';\n    const headers = Array.from(table.querySelectorAll('thead th')).map(th => th.textContent.trim());\n    const cardsWrap = document.createElement('div');\n    cardsWrap.className = 'table-cards';\n    Array.from(table.querySelectorAll('tbody tr')).forEach(tr => {\n      const cells = Array.from(tr.children);\n      if (!cells.length) return;\n      const card = document.createElement('div');\n      card.className = 'table-card';\n      if (tr.dataset.cat) card.dataset.cat = tr.dataset.cat;\n      card.dataset.searchText = tr.textContent.toLowerCase();\n      tr.__card = card;\n\n      const head = document.createElement('div');\n      head.className = 'table-card-head';\n      const primary = document.createElement('div');\n      primary.className = 'table-card-primary';\n      primary.appendChild(cells[0].cloneNode(true));\n      head.appendChild(primary);\n\n      const hasDetails = cells.length > 1;\n      let details;\n      if (hasDetails) {\n        const toggle = document.createElement('button');\n        toggle.className = 'table-card-toggle';\n        toggle.type = 'button';\n        toggle.setAttribute('aria-expanded', 'false');\n        toggle.setAttribute('aria-label', 'Ver mais detalhes');\n        toggle.innerHTML = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\"><path d=\"M6 9l6 6 6-6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>';\n        head.appendChild(toggle);\n\n        details = document.createElement('div');\n        details.className = 'table-card-details';\n        for (let i = 1; i < cells.length; i++) {\n          const label = (headers[i] || '').trim();\n          const valueHtml = cells[i].innerHTML.trim();\n          if (!valueHtml) continue;\n          const row = document.createElement('div');\n          row.className = 'table-card-row';\n          const lab = document.createElement('span');\n          lab.className = 'table-card-label';\n          lab.textContent = label || ' ';\n          const val = document.createElement('span');\n          val.className = 'table-card-value';\n          val.innerHTML = valueHtml;\n          row.append(lab, val);\n          details.appendChild(row);\n        }\n        toggle.addEventListener('click', () => {\n          const isOpen = card.classList.toggle('expanded');\n          toggle.setAttribute('aria-expanded', String(isOpen));\n        });\n      }\n\n      card.appendChild(head);\n      if (details) card.appendChild(details);\n      cardsWrap.appendChild(card);\n    });\n    wrap.insertAdjacentElement('afterend', cardsWrap);\n  });\n}\nbuildResponsiveTableCards();\n\n// ===================== KANBAN KEYBOARD NAVIGATION =====================\nfunction kanbanColumnName(col) {\n  return col.querySelector('.kanban-col-head').textContent.replace(/\\d+$/, '').trim();\n}\nfunction describeKanbanCard(card) {\n  const name = card.querySelector('strong')?.textContent || '';\n  const role = card.querySelector('.role')?.textContent || '';\n  const col = card.closest('.kanban-col');\n  const colName = col ? kanbanColumnName(col) : '';\n  card.setAttribute('aria-label', `${name}, ${role}, coluna ${colName}. Use as setas para mover entre colunas.`);\n}\ndocument.querySelectorAll('.kanban-card').forEach(card => {\n  card.setAttribute('tabindex', '0');\n  card.setAttribute('role', 'listitem');\n  describeKanbanCard(card);\n  card.addEventListener('keydown', (e) => {\n    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;\n    e.preventDefault();\n    const col = card.closest('.kanban-col');\n    const allCols = Array.from(document.querySelectorAll('.kanban-col'));\n    const idx = allCols.indexOf(col);\n    const targetCol = e.key === 'ArrowRight' ? allCols[idx + 1] : allCols[idx - 1];\n    if (!targetCol) return;\n    targetCol.querySelector('.kanban-dropzone').appendChild(card);\n    updateKanbanCounts();\n    describeKanbanCard(card);\n    card.focus();\n    card.classList.add('card-moved');\n    setTimeout(() => card.classList.remove('card-moved'), 650);\n  });\n});\n\n// ===================== PWA: SERVICE WORKER REGISTRATION =====================\nif ('serviceWorker' in navigator && (location.protocol === 'http:' || location.protocol === 'https:')) {\n  window.addEventListener('load', () => {\n    navigator.serviceWorker.register('sw.js').catch(() => { /* no real host yet — safe to ignore */ });\n  });\n}\n\n// ===================== GLOBAL COMMAND PALETTE (Ctrl+K) =====================\n(function () {\n  const overlay = document.getElementById('cmdkOverlay');\n  const input = document.getElementById('cmdkInput');\n  const resultsEl = document.getElementById('cmdkResults');\n  const trigger = document.getElementById('topbarSearchTrigger');\n  if (!overlay) return;\n\n  const icoHome = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M4 11.5 12 4l8 7.5\"/><path d=\"M6 10v9a1 1 0 0 0 1 1h4v-6h2v6h4a1 1 0 0 0 1-1v-9\"/></svg>';\n  const icoPerson = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"8\" r=\"3.2\"/><path d=\"M5 20c0-3.3 3.1-6 7-6s7 2.7 7 6\"/></svg>';\n  const icoFile = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\"/><path d=\"M9 8h6M9 12h6M9 16h3\"/></svg>';\n  const icoBolt = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M13 2 4 14h6l-1 8 9-12h-6l1-8Z\"/></svg>';\n\n  const items = [\n    { group: 'Módulos', label: 'Início', sub: 'Dashboard', icon: icoHome, view: 'view-inicio' },\n    { group: 'Módulos', label: 'Colaboradores', sub: 'Diretório e escalas', icon: icoHome, view: 'view-colaboradores' },\n    { group: 'Módulos', label: 'Recrutamento', sub: 'Vagas e pipeline', icon: icoHome, view: 'view-recrutamento' },\n    { group: 'Módulos', label: 'Onboarding', sub: 'Checklist e documentos', icon: icoHome, view: 'view-onboarding' },\n    { group: 'Módulos', label: 'Assistente RH', sub: 'Atendimento e FAQ', icon: icoHome, view: 'view-assistente' },\n    { group: 'Módulos', label: 'Analytics', sub: 'Indicadores de pessoas', icon: icoHome, view: 'view-analytics' },\n    { group: 'Módulos', label: 'Configurações', sub: 'Usuários e permissões', icon: icoHome, view: 'view-config' },\n    { group: 'Colaboradores', label: 'Marina Souza', sub: 'Analista de Marketing', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Colaboradores', label: 'Diego Ramos', sub: 'Dev Backend Jr.', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Colaboradores', label: 'Pedro Lima', sub: 'Coordenador de Logística', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Colaboradores', label: 'Ana Costa', sub: 'Analista Financeiro', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Colaboradores', label: 'Bianca Reis', sub: 'Analista de RH', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Colaboradores', label: 'Vitor Hugo', sub: 'Designer de Produto', icon: icoPerson, view: 'view-colaboradores' },\n    { group: 'Vagas', label: 'Analista de Marketing', sub: '23 candidaturas', icon: icoFile, view: 'view-recrutamento', sub2: 'recrut-vagas' },\n    { group: 'Vagas', label: 'Dev Backend Pleno', sub: '41 candidaturas', icon: icoFile, view: 'view-recrutamento', sub2: 'recrut-vagas' },\n    { group: 'Documentos', label: 'RG e CPF — Bianca Reis', sub: 'Aprovado', icon: icoFile, view: 'view-onboarding', sub2: 'onb-documentos' },\n    { group: 'Documentos', label: 'Contrato assinado — Felipe Tavares', sub: 'Em análise', icon: icoFile, view: 'view-onboarding', sub2: 'onb-documentos' },\n    { group: 'Ações', label: 'Meu perfil', sub: 'Conta e segurança', icon: icoBolt, action: 'profile' },\n    { group: 'Ações', label: '+ Nova vaga', sub: 'Recrutamento', icon: icoBolt, view: 'view-recrutamento' },\n    { group: 'Ações', label: '+ Novo colaborador', sub: 'Colaboradores', icon: icoBolt, view: 'view-colaboradores' },\n  ];\n\n  function goToSub(viewId, subId) {\n    document.querySelector(`.dock-item[data-view=\"${viewId}\"]`)?.click();\n    if (subId) {\n      setTimeout(() => {\n        document.querySelector(`#${viewId} [data-sub=\"${subId}\"]`)?.click();\n      }, 50);\n    }\n  }\n\n  let activeIndex = 0;\n  let filtered = [];\n\n  function render(query) {\n    const q = query.trim().toLowerCase();\n    filtered = !q ? items : items.filter((it) => (it.label + ' ' + it.sub + ' ' + it.group).toLowerCase().includes(q));\n    activeIndex = 0;\n    if (!filtered.length) {\n      resultsEl.innerHTML = '<div class=\"cmdk-empty\">Nada encontrado para \"' + query + '\"</div>';\n      return;\n    }\n    let html = '';\n    let lastGroup = null;\n    filtered.forEach((it, i) => {\n      if (it.group !== lastGroup) { html += `<div class=\"cmdk-group-label\">${it.group}</div>`; lastGroup = it.group; }\n      html += `<div class=\"cmdk-item${i === 0 ? ' active' : ''}\" data-idx=\"${i}\">${it.icon}<span>${it.label}</span><span class=\"cmdk-sub\">${it.sub}</span></div>`;\n    });\n    resultsEl.innerHTML = html;\n  }\n\n  function setActive(idx) {\n    activeIndex = Math.max(0, Math.min(filtered.length - 1, idx));\n    resultsEl.querySelectorAll('.cmdk-item').forEach((el) => el.classList.toggle('active', Number(el.dataset.idx) === activeIndex));\n    resultsEl.querySelector('.cmdk-item.active')?.scrollIntoView({ block: 'nearest' });\n  }\n\n  function choose(idx) {\n    const it = filtered[idx];\n    if (!it) return;\n    closeCmdk();\n    if (it.action === 'profile') { document.getElementById('goToProfile')?.click(); return; }\n    goToSub(it.view, it.sub2);\n  }\n\n  function openCmdk() {\n    overlay.classList.add('open');\n    input.value = '';\n    render('');\n    setTimeout(() => input.focus(), 30);\n  }\n  function closeCmdk() { overlay.classList.remove('open'); }\n\n  trigger.addEventListener('click', openCmdk);\n  document.addEventListener('keydown', (e) => {\n    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); openCmdk(); }\n    else if (e.key === 'Escape' && overlay.classList.contains('open')) { closeCmdk(); }\n  });\n  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeCmdk(); });\n  input.addEventListener('input', () => render(input.value));\n  input.addEventListener('keydown', (e) => {\n    if (e.key === 'ArrowDown') { e.preventDefault(); setActive(activeIndex + 1); }\n    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive(activeIndex - 1); }\n    else if (e.key === 'Enter') { e.preventDefault(); choose(activeIndex); }\n  });\n  resultsEl.addEventListener('click', (e) => {\n    const item = e.target.closest('.cmdk-item');\n    if (item) choose(Number(item.dataset.idx));\n  });\n})();\n\n// ===================== BUTTON RIPPLE (microinteração) =====================\nif (!reduceMotion) {\n  document.addEventListener('click', (e) => {\n    const btn = e.target.closest('.btn');\n    if (!btn) return;\n    const rect = btn.getBoundingClientRect();\n    const ripple = document.createElement('span');\n    ripple.className = 'btn-ripple';\n    const size = Math.max(rect.width, rect.height) * 1.6;\n    ripple.style.width = ripple.style.height = size + 'px';\n    ripple.style.left = (e.clientX - rect.left - size / 2) + 'px';\n    ripple.style.top = (e.clientY - rect.top - size / 2) + 'px';\n    btn.appendChild(ripple);\n    setTimeout(() => ripple.remove(), 650);\n  });\n}\n\n// ===================== DADOS REAIS (injetados pelo Next.js via query string) =====================\n// Substitui os valores de demonstração do protótipo pelos números reais vindos\n// do Supabase (contados no servidor, isolados por tenant via RLS) e liga o\n// botão \"Sair\" ao logout real da aplicação, via postMessage pro parent (esta\n// página roda dentro de um iframe em /dashboard).\n(function () {\n  const params = new URLSearchParams(window.location.search);\n\n  function setText(id, value) {\n    const el = document.getElementById(id);\n    if (el && value != null) el.textContent = value;\n  }\n\n  const fullName = params.get('name');\n  const firstName = fullName ? fullName.split(' ')[0] : null;\n  const initials = fullName\n    ? fullName.trim().split(/\\s+/).map((p) => p[0]).slice(0, 2).join('').toUpperCase()\n    : null;\n\n  setText('topbarProfileName', fullName);\n  setText('topbarAvatar', initials);\n\n  if (firstName) {\n    const hour = new Date().getHours();\n    const saudacao = hour < 12 ? 'Bom dia' : hour < 18 ? 'Boa tarde' : 'Boa noite';\n    setText('dashGreeting', `${saudacao}, ${firstName} 👋`);\n  }\n  const tenantName = params.get('tenant');\n  const planLabel = params.get('plan');\n  if (tenantName) {\n    const dateLabel = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });\n    setText('dashGreetingSub', `${tenantName}${planLabel ? ' · plano ' + planLabel : ''} · ${dateLabel}`);\n  }\n\n  setText('kpiColaboradores', params.get('kpiColaboradores'));\n  setText('kpiVagas', params.get('kpiVagas'));\n  setText('kpiOnboardings', params.get('kpiOnboardings'));\n  setText('kpiSolicitacoes', params.get('kpiSolicitacoes'));\n\n  const signOutBtn = document.getElementById('signOutBtn');\n  if (signOutBtn) {\n    signOutBtn.addEventListener('click', () => {\n      window.parent.postMessage({ type: 'fortixx:sign-out' }, window.location.origin);\n    });\n  }\n\n  // Módulos ainda não conectados a dados reais nesta fase (Colaboradores,\n  // Recrutamento, Onboarding, Assistente RH, Analytics, Configurações) seguem\n  // com o conteúdo de demonstração do protótipo original — ver README.md.\n})();\n";
